from itertools import combinations
from math import gcd
from typing import Set, Tuple

Cell = Tuple[int, int]

def attacks(a: Cell, b: Cell) -> bool:
    return (a[0] == b[0] or a[1] == b[1]
            or a[0] + a[1] == b[0] + b[1]
            or a[0] - a[1] == b[0] - b[1])

def is_full_solution(q: Set[Cell], n: int) -> bool:
    return len(q) == n and all(not attacks(a, b)
                               for a, b in combinations(sorted(q), 2))

def diag_graph(n: int, b: int) -> Set[Cell]:
    return {(x, (2 * x + b) % n) for x in range(n)}

for n in range(1, 41):
    sols = [b for b in range(n) if is_full_solution(diag_graph(n, b), n)]
    if gcd(n, 6) == 1:
        assert len(sols) == n, (n, sols)
        print(f'n={n:2d} gcd=1 : full solution for all {n} offsets -> OK')
    else:
        assert sols == [], (n, sols)
        print(f'n={n:2d} gcd={gcd(n,6)} : no slope-2 solution (expected)')

