def _augment(row, adj, match_col, seen):
    for col in adj[row]:
        if col in seen:
            continue
        seen.add(col)
        if col not in match_col or _augment(match_col[col], adj, match_col, seen):
            match_col[col] = row
            return True
    return False

def hall_repair(n: int, q: Set[Cell]) -> Optional[Set[Cell]]:
    ur = {r for r, _ in q}; uc = {c for _, c in q}
    fa = {r + c for r, c in q}; fm = {r - c for r, c in q}
    er = [r for r in range(n) if r not in ur]
    ec = [c for c in range(n) if c not in uc]
    adj = {r: [c for c in ec if (r+c) not in fa and (r-c) not in fm] for r in er}
    mc: Dict[int, int] = {}
    for r in er:
        if not _augment(r, adj, mc, set()):
            return None
    p = set(q)
    for c, r in mc.items():
        p.add((r, c))
    return p

for n in [25, 31, 37]:
    full = sorted({(x, (2 * x) % n) for x in range(n)})
    q = set(full[: n // 5])
    p = hall_repair(n, q)
    new = p - q
    ok = (len(p) == n and q <= p
          and all(not attacks(a, b) for a in new for b in q))
    print(f'n={n:2d}: |Q|={n//5} -> permutation of {len(p)} queens, no new-old conflict -> {ok}')

