  require gcd(n, 6) == 1
  b <- (c - 2*r) mod n
  return diag_graph(n, b)   # full solution, contains (r, c)

function hall_repair(n, Q):
  require Q non-attacking and 5*|Q| <= n
  empty_rows <- rows not used by Q
  empty_cols <- columns not used by Q
  forbidden_anti <- { r+c : (r,c) in Q }
  forbidden_main <- { r-c : (r,c) in Q }
  for each empty row r:
      adj[r] <- { c in empty_cols : r+c not in forbidden_anti
                                 and r-c not in forbidden_main }
  M <- maximum bipartite matching of empty_rows into empty_cols using adj
  if M saturates empty_rows: return Q union M
  else: return FAIL

